import { Component, OnInit, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { ApiService } from '../../services/api.service';
import { Animal, AnimalCard } from '../../models/animal.model';

@Component({
  selector: 'app-animal-matching',
  templateUrl: './animal-matching.component.html',
  styleUrls: ['./animal-matching.component.css']
})
export class AnimalMatchingComponent implements OnInit, OnDestroy {
  cards: AnimalCard[] = [];
  flippedCards: AnimalCard[] = [];
  matchedCount = 0;
  score = 0;
  moves = 0;
  level = 1;
  gameStarted = false;
  gameWon = false;
  playerName = '';
  timer = 0;
  timerInterval: any;
  isChecking = false;
  animals: Animal[] = [];
  scoreMessage = '';
  matchMode: 'emoji-name' | 'emoji-sound' | 'emoji-emoji' = 'emoji-name';
  showNameInput = true;
  loadingAnimals = false;

  constructor(private router: Router, private apiService: ApiService) {}

  ngOnInit() {
    this.loadAnimals();
  }

  ngOnDestroy() {
    this.clearTimer();
  }

  loadAnimals() {
    this.loadingAnimals = true;
    this.apiService.getAnimals().subscribe({
      next: (res) => {
        this.animals = res.data;
        this.loadingAnimals = false;
      },
      error: () => {
        // Fallback data if API is down
        this.animals = [
          { name: 'Dog', emoji: '🐶', sound: 'Woof!', soundEmoji: '🔊', difficulty: 1 },
          { name: 'Cat', emoji: '🐱', sound: 'Meow!', soundEmoji: '🔊', difficulty: 1 },
          { name: 'Cow', emoji: '🐮', sound: 'Moo!', soundEmoji: '🔊', difficulty: 1 },
          { name: 'Duck', emoji: '🦆', sound: 'Quack!', soundEmoji: '🔊', difficulty: 1 },
          { name: 'Pig', emoji: '🐷', sound: 'Oink!', soundEmoji: '🔊', difficulty: 1 },
          { name: 'Sheep', emoji: '🐑', sound: 'Baa!', soundEmoji: '🔊', difficulty: 2 },
        ];
        this.loadingAnimals = false;
      }
    });
  }

  startGame() {
    if (!this.playerName.trim()) { alert('Please enter your name!'); return; }
    this.showNameInput = false;
    this.initGame();
  }

  initGame() {
    this.score = 0; this.moves = 0; this.matchedCount = 0;
    this.timer = 0; this.gameWon = false; this.flippedCards = [];
    this.scoreMessage = '';

    const animalCount = this.level <= 1 ? 4 : this.level <= 2 ? 6 : 8;
    const shuffled = [...this.animals].sort(() => Math.random() - 0.5);
    const selected = shuffled.slice(0, animalCount);

    // Create pairs: emoji + name (or sound)
    this.cards = [];
    selected.forEach((animal, i) => {
      const pairId = `pair-${i}`;
      // Card A: emoji
      this.cards.push({
        id: `${pairId}-a`,
        animal,
        type: 'image',
        isFlipped: false,
        isMatched: false,
        content: animal.emoji
      });
      // Card B: name or sound
      const showSound = this.matchMode === 'emoji-sound';
      this.cards.push({
        id: `${pairId}-b`,
        animal,
        type: showSound ? 'sound' : 'name',
        isFlipped: false,
        isMatched: false,
        content: showSound ? animal.sound : animal.name
      });
    });

    this.cards = this.cards.sort(() => Math.random() - 0.5);
    this.gameStarted = true;
    this.startTimer();
  }

  flipCard(card: AnimalCard) {
    if (this.isChecking || card.isFlipped || card.isMatched) return;
    if (this.flippedCards.length >= 2) return;

    card.isFlipped = true;
    this.flippedCards.push(card);

    if (this.flippedCards.length === 2) {
      this.moves++;
      this.checkMatch();
    }
  }

  checkMatch() {
    this.isChecking = true;
    const [a, b] = this.flippedCards;

    // Match if same animal but different card types
    const isMatch = a.animal.name === b.animal.name && a.type !== b.type;

    setTimeout(() => {
      if (isMatch) {
        a.isMatched = true;
        b.isMatched = true;
        this.matchedCount++;
        this.score += Math.max(10, 30 - this.moves);

        const totalPairs = this.cards.length / 2;
        if (this.matchedCount === totalPairs) {
          this.handleWin();
        }
      } else {
        a.isFlipped = false;
        b.isFlipped = false;
        this.score = Math.max(0, this.score - 2);
      }
      this.flippedCards = [];
      this.isChecking = false;
    }, 900);
  }

  handleWin() {
    this.clearTimer();
    this.gameWon = true;
    const timeBonus = Math.max(0, 100 - this.timer);
    this.score += timeBonus;
    this.scoreMessage = `🎉 Amazing! +${timeBonus} time bonus!`;

    this.apiService.saveScore({
      playerName: this.playerName,
      gameType: 'animal-matching',
      score: this.score,
      level: this.level,
      timeTaken: this.timer
    }).subscribe({ error: () => {} });
  }

  nextLevel() {
    this.level = Math.min(this.level + 1, 3);
    this.initGame();
  }

  changeMode(mode: 'emoji-name' | 'emoji-sound' | 'emoji-emoji') {
    this.matchMode = mode;
  }

  startTimer() {
    this.clearTimer();
    this.timerInterval = setInterval(() => this.timer++, 1000);
  }

  clearTimer() {
    if (this.timerInterval) { clearInterval(this.timerInterval); }
  }

  formatTime(s: number): string {
    return `${Math.floor(s / 60).toString().padStart(2,'0')}:${(s % 60).toString().padStart(2,'0')}`;
  }

  get totalPairs(): number { return this.cards.length / 2; }

  goHome() { this.router.navigate(['/']); }
}
<!-- Name Input Screen -->
<div class="game-container" *ngIf="showNameInput">
  <div class="name-screen">
    <button class="back-btn" (click)="goHome()">← Back</button>
    <div class="title-area">
      <div class="big-emoji">🐾</div>
      <h1>Animal Matching!</h1>
      <p>Match animals with their names and sounds</p>
    </div>

    <div class="options-panel">
      <h3>Match Mode:</h3>
      <div class="mode-buttons">
        <button [class.active]="matchMode === 'emoji-name'" (click)="changeMode('emoji-name')">🐶 ↔ Name</button>
        <button [class.active]="matchMode === 'emoji-sound'" (click)="changeMode('emoji-sound')">🐶 ↔ Sound</button>
      </div>

      <h3>Difficulty:</h3>
      <div class="mode-buttons">
        <button [class.active]="level === 1" (click)="level = 1">⭐ Easy (4 pairs)</button>
        <button [class.active]="level === 2" (click)="level = 2">⭐⭐ Medium (6 pairs)</button>
        <button [class.active]="level === 3" (click)="level = 3">⭐⭐⭐ Hard (8 pairs)</button>
      </div>
    </div>

    <div class="name-input-area">
      <label>Your Name:</label>
      <input type="text" [(ngModel)]="playerName" placeholder="Enter your name..." maxlength="20" (keyup.enter)="startGame()">
      <button class="start-btn" (click)="startGame()">🎮 Start Game!</button>
    </div>
  </div>
</div>

<!-- Game Screen -->
<div class="game-container" *ngIf="gameStarted && !showNameInput">
  <div class="game-header">
    <button class="back-btn" (click)="goHome()">← Home</button>
    <div class="stats">
      <span class="stat">⏱️ {{formatTime(timer)}}</span>
      <span class="stat">🎯 {{matchedCount}}/{{totalPairs}}</span>
      <span class="stat">🌟 {{score}} pts</span>
      <span class="stat">🔄 {{moves}} moves</span>
    </div>
    <span class="level-badge">Level {{level}}</span>
  </div>

  <div class="mode-info">
    <span *ngIf="matchMode === 'emoji-name'">Match the 🐾 animal with its <strong>Name</strong>!</span>
    <span *ngIf="matchMode === 'emoji-sound'">Match the 🐾 animal with its <strong>Sound</strong>!</span>
  </div>

  <!-- Cards Grid -->
  <div class="cards-grid" [class.grid-4]="totalPairs <= 4" [class.grid-6]="totalPairs === 6" [class.grid-8]="totalPairs >= 7">
    <div
      *ngFor="let card of cards"
      class="card"
      [class.flipped]="card.isFlipped || card.isMatched"
      [class.matched]="card.isMatched"
      [class.is-name]="card.type === 'name'"
      [class.is-sound]="card.type === 'sound'"
      (click)="flipCard(card)">
      <div class="card-inner">
        <div class="card-front">❓</div>
        <div class="card-back">
          <span class="card-content">{{card.content}}</span>
          <span class="card-label" *ngIf="card.type === 'name'">✏️ Name</span>
          <span class="card-label" *ngIf="card.type === 'sound'">🔊 Sound</span>
          <span class="card-label" *ngIf="card.type === 'image'">🐾 Animal</span>
        </div>
      </div>
    </div>
  </div>

  <!-- Win Screen -->
  <div class="win-overlay" *ngIf="gameWon">
    <div class="win-card">
      <div class="win-emoji">🏆</div>
      <h2>You Won, {{playerName}}!</h2>
      <p>{{scoreMessage}}</p>
      <div class="win-stats">
        <div class="win-stat"><span>⭐ Score</span><strong>{{score}}</strong></div>
        <div class="win-stat"><span>⏱️ Time</span><strong>{{formatTime(timer)}}</strong></div>
        <div class="win-stat"><span>🔄 Moves</span><strong>{{moves}}</strong></div>
      </div>
      <div class="win-actions">
        <button (click)="nextLevel()" *ngIf="level < 3">🚀 Next Level!</button>
        <button (click)="initGame()">🔄 Play Again</button>
        <button class="home-btn" (click)="goHome()">🏠 Home</button>
      </div>
    </div>
  </div>
</div>
